#!/usr/bin/env bash
#
# Round-trips a trivial program through each managed toolchain in the
# dev-managed image. Its purpose is diagnostic isolation: once the JVM backend
# exists, a failure here means the image is broken or version-skewed, and a
# failure there means the generated bytecode is wrong. Without it, the first
# backend commit debugs both at once.
#
# Also prints exact toolchain versions, since the HotSpot version is part of
# any performance baseline measured through this backend.
set -euo pipefail

fixtures="$(cd "$(dirname "${BASH_SOURCE[0]}")/toolchain_smoke" && pwd)"
repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

failures=0

check() {
    local name="$1" expected="$2" actual="$3"
    if [ "$actual" = "$expected" ]; then
        printf '  ok    %s\n' "$name"
    else
        printf '  FAIL  %s\n          expected: %s\n          actual:   %s\n' \
            "$name" "$expected" "$actual"
        failures=$((failures + 1))
    fi
}

# Compile and assemble steps have to report through the same path as everything
# else. As bare commands under `set -e` they abort the script before `check` runs,
# so a broken assembler — the failure mode that produces the least output — would
# surface as a bare nonzero exit. Output is captured and printed only on failure,
# so discarding it would throw away the only explanation of what went wrong.
step() {
    local name="$1"; shift
    local out
    if out="$("$@" 2>&1)"; then
        return 0
    fi
    printf '  FAIL  %s\n' "$name"
    printf '%s\n' "$out" | sed 's/^/          /'
    failures=$((failures + 1))
    return 1
}

cd "$work"
cp "$fixtures/Hello.java" "$fixtures/hello.j" "$fixtures/branch.j" .

# Jasmin prints its banner and exits nonzero when invoked with no arguments, so
# this probe must not be allowed to trip `set -e` — the banner is what we are
# after, not the status.
echo "== toolchain versions =="
java -version 2>&1 | sed 's/^/  /' || true
printf '  javac %s\n' "$(javac -version 2>&1 | awk '{print $2}' || true)"
printf '  jasmin %s\n' \
    "$(java -jar /opt/jasmin/jasmin.jar -version 2>&1 | awk '/Jasmin/ {print $3; exit}' || true)"

echo
echo "== round-trips =="

# 1. JDK alone — isolates a broken JDK from a broken Jasmin.
if step "javac" javac Hello.java; then
    check "javac -> java" "javac ok" "$(java Hello 2>&1 || true)"
fi

# 2. Jasmin: the path the JVM backend emits into.
if step "jasmin assembly" jasmin -d . hello.j; then
    check "jasmin -> java" "jasmin ok" "$(java HelloJasmin 2>&1 || true)"

    # Asserted, not merely logged: both backend plans rest on this version
    # staying below the frame requirement, so it should fail loudly rather than
    # print a number nothing reads.
    check "jasmin class file version" "45.3" \
        "$(javap -v HelloJasmin.class 2>/dev/null \
            | awk '/major version/ {maj = $3} /minor version/ {min = $3}
                   END {print maj "." min}' || true)"
fi

# 2b. Branching bytecode — the case that actually bears on frames. A v51+ class
#     file with these branches and no StackMapTable fails verification outright;
#     at exactly v50 HotSpot still fails over to the old type-inferencing
#     verifier, so v51 is where this check starts biting. 45.3 sits below both.
if step "jasmin assembly (branching)" jasmin -d . branch.j; then
    check "jasmin -> java (branching)" "branching ok" \
        "$(java BranchProbe 2>&1 || true)"
fi

# 2c. lox-rt link: a hand-written class calls lox.LoxOps.print and links
# against lox-rt.jar, through tools/jvm_run.sh — the same harness a code
# generator will call. This proves the assemble -> run -> link chain end to
# end, before any code generator exists. Run through jvm_run.sh itself, not a
# second copy of its jasmin/java calls, so a regression there shows up here
# too. Must fail loudly, not skip, when the jar is missing: a passing check
# must mean the link happened, not that it was never attempted.
mkdir -p hellort
cp "$fixtures/HelloRt.j" hellort/
check "jvm_run.sh -> java (lox-rt link)" "lox-rt ok" \
    "$("$repo_root/tools/jvm_run.sh" hellort "$repo_root/runtime/jvm/lox-rt.jar" HelloRt 2>&1 || true)"

echo
if [ "$failures" -ne 0 ]; then
    echo "$failures managed toolchain check(s) failed."
    exit 1
fi
echo "All managed toolchain checks passed."
